$(function(){/(iPhone|iPad|iPod)/i.test(navigator.userAgent)&&window.addEventListener("load",function(){setTimeout(scrollTo,0,0,1)},!1);if(!!window.ActiveXObject){$bgImg=function(){$winWidth=document.body.clientWidth;$winHeight=document.body.clientHeight;$imgHeight=1080/(1920/$winWidth);$(".ie-bg img").width($winWidth).height($imgHeight)};$bgImg();window.onresize=$bgImg}$(".go-top").click(function(){$("html,body").animate({scrollTop:0},1e3)});$("a.at").click(function(){$link=$(this).attr("data-link");$point=$($link).offset().top;$("html,body").animate({scrollTop:$point},1e3)})});